action.code:
if (internal_key.size() < 8) {
  return false;
}
const size_t n = internal_key.size();
uint64_t packed = DecodeFixed64(internal_key.data() + n - 8);
uint8_t t = static_cast<uint8_t>(packed & 0xff);
uint64_t seq = packed >> 8;
if (t > kValueTypeForSeek) {
  return false;
}
*user_key = Slice(internal_key.data(), n - 8);
*sequence = seq;
*type = t;
return true;

